-- Datos demo del CRM B2B de Ice Gym (generado por gen_seed.py). Fechas relativas a now().
-- Borra y vuelve a poblar: equipo, empresas, contactos, oportunidades, interacciones.

create or replace function pg_temp.t(d int, h int, m int) returns timestamptz language sql stable as $$ select date_trunc('day', now()) + make_interval(days => d, hours => h, mins => m) $$;

delete from interacciones;
delete from oportunidades;
delete from contactos;
delete from empresas;
delete from equipo;

